contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address newOwner, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount == 0);
        require(address(this).balance >= amount);
        uint cBalBefore = address(c).balance;
        bool reverted = false;
        bool success = false;
        // top-level state-changing call (no value attached; amount is 0)
        success = c.setOwner(newOwner); if (__ESBMC_reverted()) return;
        assert(!reverted && success && c.owner() == newOwner && address(c).balance == cBalBefore);
    }
    receive() external payable {}
}

