// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address newOwner, uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        amount = 0;
        vm.assume(address(this).balance >= amount);
        uint cBalBefore = address(c).balance;
        bool reverted = false;
        bool success = false;
        try c.setOwner(newOwner) returns (bool __r) { success = __r; } catch { return; }
        assertTrue(!reverted && success && c.owner() == newOwner && address(c).balance == cBalBefore);
    }

    function testFuzz_run(address newOwner, uint256 amount) public {
        vm.assume(newOwner.code.length == 0 && uint160(newOwner) > 0xffff && newOwner != address(this) && newOwner != address(c) && newOwner != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && newOwner != 0x000000000000000000636F6e736F6c652e6c6f67 && newOwner != 0x4e59b44847b379578588920cA78FbF26c0B4956C && newOwner != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(newOwner, amount);
    }

    receive() external payable {}
}
